Implement the Verilog module based on the following description.
Build an 8-bit Johnson counter with synchronous active high reset signal. The counter should shift its bits to the left and invert the least significant bit to form the next state.
// (1) reset: Resets the counter to 8'b00000001 when high.
// (2) q: The value of the counter.

module top_module(
    input clk,
    input reset,
    output reg [7:0] q);

code:
module top_module(
    input clk,
    input reset,
    output reg [7:0] q
);

    always @(posedge clk) begin
        if (reset) begin
            // Synchronous reset: Reset the counter to 8'b00000001
            q <= 8'b00000001;
        end else begin
            // Johnson counter: Shift left and invert the LSB
            q <= {q[6:0], ~q[7]};
        end
    end

endmodule

