module top_module(
  input [266:0] data,
  input rdclk,
  input rdreq,
  input wrclk,
  input wrreq,
  output reg [266:0] q,  // Change from wire to reg
  output rdempty,
  output wrempty,
  output wrfull,
  output [6:0] wrusedw
);// Define FIFO parameters
  parameter WIDTH = 267;
  parameter DEPTH = 128;
  parameter ADDR_WIDTH = $clog2(DEPTH);
  parameter DATA_WIDTH = WIDTH + ADDR_WIDTH;

  // Define FIFO memory
  reg [DATA_WIDTH-1:0] mem [0:DEPTH-1];

  // Define FIFO pointers
  reg [ADDR_WIDTH-1:0] wr_ptr;
  reg [ADDR_WIDTH-1:0] rd_ptr;
  reg [ADDR_WIDTH-1:0] next_wr_ptr;
  reg [ADDR_WIDTH-1:0] next_rd_ptr;

  // Define FIFO status signals
  wire empty = (wr_ptr == rd_ptr);
  wire full = ((next_wr_ptr == rd_ptr) && (wr_ptr != rd_ptr));
  wire [6:0] usedw = (wr_ptr > rd_ptr) ? (wr_ptr - rd_ptr) : (DEPTH - (rd_ptr - wr_ptr)); // Ensure usedw is 7 bits

  // Define write logic
  always @(posedge wrclk) begin
    if (wrreq && !full) begin
      mem[wr_ptr][WIDTH-1:0] <= data; // Non-blocking assignment
      next_wr_ptr <= wr_ptr + 1; // Non-blocking assignment
    end
  end

  // Define read logic
  always @(posedge rdclk) begin
    if (rdreq && !empty) begin
      q <= mem[rd_ptr][WIDTH-1:0]; // Non-blocking assignment
      next_rd_ptr <= rd_ptr + 1; // Non-blocking assignment
    end
  end

  // Define pointer update logic
  always @(*) begin
    if (wrreq && !full) begin
      wr_ptr <= next_wr_ptr; // Non-blocking assignment
    end
    if (rdreq && !empty) begin
      rd_ptr <= next_rd_ptr; // Non-blocking assignment
    end
  end

  // Define status signals
  assign rdempty = empty;
  assign wrempty = full;
  assign wrfull = full;
  assign wrusedw = usedw;

endmodule

