            V = 1'b1;
        end else if (B) begin
            Y = 2'b01;
            V = 1'b1;
        end else if (C) begin
            Y = 2'b10;
            V = 1'b1;
        end else if (D) begin
            Y = 2'b11;
            V = 1'b1;
        end else begin
            Y = 2'b00;
            V = 1'b0;
        end
    end

endmodule

