module top_module(RDATA, RCLK, RCLKE, RE, RADDR, WCLK, WCLKE, WE, WADDR, MASK, WDATA);output reg [15:0] RDATA;  // Changed to reg type
  input RCLK, RCLKE, RE;
  input [11:0] RADDR;
  input WCLK, WCLKE, WE;
  input [11:0] WADDR;
  input [15:0] MASK, WDATA;

  reg [15:0] ram[0:4095];

  always @(posedge WCLK) begin
    if (WCLKE && WE) begin
      ram[WADDR] <= (MASK & WDATA) | (~MASK & ram[WADDR]);
    end
  end

  always @(posedge RCLK) begin
    if (RCLKE && RE) begin
      RDATA <= ram[RADDR];
    end
  end

endmodule

