module top_module(clk, green, red);parameter GREEN_TIME = 10;
   parameter YELLOW_TIME = 2;
   parameter RED_TIME = 10;

   input clk;
   output reg green;
   output reg red;

   reg [3:0] state;
   reg [3:0] counter;

   always @(posedge clk) begin
      case(state)
         4'b0000: begin
            green <= 1;
            red <= 0;
            if(counter == GREEN_TIME) begin
               counter <= 0;
               state <= 4'b0001;
            end else begin
               counter <= counter + 1;
            end
         end
         4'b0001: begin
            green <= 1;
            red <= 1;
            if(counter == YELLOW_TIME) begin
               counter <= 0;
               state <= 4'b0010;
            end else begin
               counter <= counter + 1;
            end
         end
         4'b0010: begin
            green <= 0;
            red <= 1;
            if(counter == RED_TIME) begin
               counter <= 0;
               state <= 4'b0000;
            end else begin
               counter <= counter + 1;
            end
         end
         default: begin
            green <= 0;
            red <= 0;
            counter <= 0;
            state <= 4'b0000;
         end
      endcase
   end

endmodule

