  ack_o <= 1'b0; 
  else 
  ack_o <= wb_acc & !ack_o; 
  always @(posedge clk_i) 
  case({tx,rx}) 
  2'b00 : rgpio <= idle_out; 
  2'b01 : rgpio <= rx_out; 
  2'b10 : rgpio <= tx_out; 
  2'b11 : rgpio <= fdx_out; 
  endcase 
  always @* 
  for(n=0;n<32;n=n+1) 
  igpio[n] <= ddr[n] ? rgpio[n] : 1'bz; 
  assign gpio = igpio; 
 endmodule

