			ERR1 <= ERR1 + 1;
		if(DATA_TEMP[23:16] + 1 != DATA[23:16] && DATA[23:16] != 0)
			ERR2 <= ERR2 + 1;
		if(DATA_TEMP[31:24] + 1 != DATA[31:24] && DATA[31:24] != 0)
			ERR3 <= ERR3 + 1;
		if(MSG[39:32] + 1 != MSG[31:24] || MSG[31:24] + 1 != MSG[23:16] || MSG[23:16] + 1 != MSG[15:8] || MSG[15:8] + 1 != MSG[7:0])
			ERR_MSG <= ERR_MSG + 1;
	end
end
