code:
module top_module(
    input clk,
    input load,
    input ena,
    input [15:0] data,
    output reg [15:0] q
);

    always @(posedge clk) begin
        if (load) begin
            // Load: Load the data into the counter
            q <= data;
        end else if (ena) begin
            // Enable: Decrement the counter
            q <= q - 1;
        end
    end

endmodule

