module top_module (
        input clk,
        input reset,
        input a,
        output reg y);parameter S0=0, S1=1, S2=2, S3=3, S4=4;
	reg[2:0] state, next;

	always @(posedge clk)
		if (reset) state <= S0;
		else state <= next;


	always_comb begin
		case (state)
			S0: next = a ? S1 : S0;
			S1: next = a ? S2 : S3;
			S2: next = a ? S4 : S3;
			S3: next = a ? S4 : S0;
			S4: next = a ? S1 : S0;
			default: next = 'x;
		endcase
	end

	assign y = (state == S2) || (state == S3);

endmodule

