module top_module(
    input clk,
    input reset,
    input [254:0] in,
    output [7:0] out
);// Define the shift register
    reg [254:0] shift_reg;
    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 255'b0;
        end else begin
            shift_reg <= {shift_reg[253:0], in};
        end
    end

    // Define the adder
    reg [7:0] count;
    always @(posedge clk) begin
        if (reset) begin
            count <= 8'b0;
        end else begin
            count <= count + (~shift_reg[0]);
        end
    end

    // Define the comparator
    assign out = (count == 8'hFF);

endmodule

