    if (~rst_n) begin
        data_reg <= 8'b0;
        count_reg <= 4'b0;
        valid_b <= 1'b0;
        data_out <= 10'b0;
    end else begin
        if (valid_a && ready_b) begin
            data_reg <= data_reg + data_in;
            count_reg <= count_reg + 1;
            if (count_reg == 4'b1000) begin
                valid_b <= 1'b1;
                data_out <= {2'b0, data_reg};
                count_reg <= 4'b0;
            end
        end
    end
end

assign ready_a = ~valid_b;

endmodule

